function writingFields(root){return [...root.querySelectorAll('textarea,input:not([type]),input[type="text"],input[type="search"]')].filter(f=>!f.disabled&&!f.readOnly&&!f.closest('[inert]'));}
function attachWritingTools(root){
 root.querySelectorAll('.write-tools').forEach(t=>{const parent=t.parentElement;t.remove();if(parent?.tagName==='DIV'&&parent.hasAttribute('style')&&!parent.children.length&&!parent.textContent.trim())parent.remove();});
 const fields=writingFields(root);if(!fields.length)return;
 const holder=document.createElement('div');holder.className='write-tools shared-write-tools';
 holder.innerHTML='<select class="writing-target" aria-label="Choose a field to write in"><option value="">Choose a field…</option></select><button type="button" data-action="pencil" aria-pressed="'+document.body.classList.contains('pencil-mode')+'" title="Use Apple Pencil Scribble in the selected field">✎ Pencil</button><button type="button" data-action="dictate">● Dictate</button>';
 const select=holder.querySelector('select');
 fields.forEach(field=>{const key='writing-'+(++writingSequence);field.dataset.writingKey=key;const option=document.createElement('option');option.value=key;option.textContent=field.getAttribute('aria-label')||field.closest('label')?.firstChild?.textContent?.trim()||field.name||'Writing';select.append(option);});
 if(root===app)root.querySelector('.book-head').after(holder);else root.querySelector('.modal-head').after(holder);
 select.addEventListener('change',()=>{const field=fields.find(f=>f.dataset.writingKey===select.value);if(field){focusField=field;field.focus({preventScroll:true});field.scrollIntoView({block:'nearest',inline:'nearest'});}});
 holder.addEventListener('pointerdown',e=>{if(e.target.closest('button'))e.preventDefault();});
 if(focusField?.isConnected&&fields.includes(focusField))select.value=focusField.dataset.writingKey;else focusField=null;
}
function chooseWritingField(button){
 const root=button.closest('#modal-content')||app;
 if(!focusField?.isConnected||!root.contains(focusField))focusField=writingFields(root)[0]||null;
 if(focusField){const select=root.querySelector('.writing-target');if(select)select.value=focusField.dataset.writingKey;focusField.focus({preventScroll:true});}
 return focusField;
}
function rememberPage(){try{localStorage.setItem(KEY+'-last-page',JSON.stringify({date,section,view,noteId}));}catch{}}
function renderRibbons(){document.querySelector('.named-ribbons')?.remove();const shell=document.querySelector('.book-shell')||document.querySelector('.cover-book');if(!shell)return;const nav=document.createElement('nav');nav.className='named-ribbons';nav.setAttribute('aria-label','Bookmarked pages');if(closed)nav.classList.add('cover-bookmarks');nav.innerHTML=(state.bookmarks||[]).map((r,i)=>`<button data-ribbon="${r.id}" class="fabric-ribbon" aria-label="Open bookmark ${esc(r.name)}" style="--ribbon-colour:${/^#[a-f0-9]{6}$/i.test(r.color)?r.color:'#725142'};--ribbon-length:${94+(i%3)*12}px;--ribbon-tilt:${[-3,2,-1,3][i%4]}deg" title="${esc(r.name)}"><span class="ribbon-fabric"><span class="ribbon-label">${esc(r.name)}</span></span></button>`).join('')+'<button class="ribbon-add" data-action="ribbons" aria-label="Manage named ribbons">+ Ribbon</button>';shell.append(nav);}
function ribbonManager(){openModal('Your named ribbons',`<p>Keep a ribbon at the page you’re viewing. Your ribbons are included in notebook backups.</p><div class="ribbon-list">${(state.bookmarks||[]).map(r=>`<div><button class="secondary" data-ribbon="${r.id}">${esc(r.name)}</button><button type="button" class="text-action" data-remove-ribbon="${r.id}" aria-label="Remove ${esc(r.name)} ribbon">Remove</button></div>`).join('')}</div><form id="ribbon-form"><label>Name for this page<input type="text" name="name" maxlength="40" required placeholder="For example, My ideas"></label><label class="check-label">Ribbon colour<select name="color"><option value="#725142">Cognac</option><option value="#426653">Forest</option><option value="#344e6e">Navy</option><option value="#863f52">Burgundy</option><option value="#9c7329">Antique gold</option><option value="#357e83">Peacock teal</option><option value="#685080">Plum</option><option value="#b15435">Copper</option></select></label><div class="modal-footer"><button class="primary" type="submit">Bookmark this page</button></div></form>`);}
function backupSetup(){openModal('Keep your days safe',`<p>Your calendar and notebook save automatically on this device. A cloud copy lets you recover them if your iPad is lost, and continue on another device.</p><div class="backup-providers"><button class="secondary" data-action="backup-choose-google"><strong>Google Drive</strong><span>${state.settings.googleClientId||cloudConfig.googleClientId?'Connect your Google account':'Connection setup required'}</span></button><button class="secondary" data-action="backup-choose-dropbox" ${cloudConfig.dropboxAppKey?'':'disabled'}><strong>Dropbox</strong><span>${cloudConfig.dropboxAppKey?'Connect your Dropbox account':'Awaiting application registration'}</span></button><button class="secondary" disabled><strong>Box</strong><span>Secure connection service required</span></button></div><p class="scratch-note">Cloud providers require a registered application and your consent. No connection is claimed until sign-in succeeds. Google Calendar synchronises appointments; notebook backup additionally includes notes, goals, tasks, pen strokes and ribbons.</p><div class="backup-steps"><p><strong>1.</strong> Choose a cloud account and connect it.</p><p><strong>2.</strong> Wait for “Saved · cloud copy” before relying on that backup.</p><p><strong>3.</strong> On another device, open Unbound Days and connect the same account. Review any conflicts before applying changes.</p></div><button class="secondary" data-action="export-backup">Save complete notebook to Files</button><p class="scratch-note">On iPad, keep this JSON file in Files → On My iPad, or choose your Google Drive, Dropbox or Box folder in Files. To recover, use Settings → Restore from file. This includes your original ink, not just a printed calendar.</p><div class="modal-footer"><button class="secondary" data-action="backup-later">Set up later</button><button class="primary" data-action="protect-storage">Protect device storage</button></div>`);}

function attachQuickDelete(root){
 const add=(el,attribute,value,label,extra={})=>{if(el.closest('[inert]')||el.dataset.quickDeleteAttached)return;el.dataset.quickDeleteAttached='true';const b=document.createElement('button');b.type='button';b.className='quick-delete';b.setAttribute(attribute,value);for(const [key,v]of Object.entries(extra))b.setAttribute(key,v);b.setAttribute('aria-label','Delete '+label);b.title='Delete '+label;b.innerHTML='<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg>';el.after(b);};
 root.querySelectorAll('[data-edit-event]').forEach(el=>add(el,'data-delete-event',el.dataset.editEvent,el.textContent.trim()));
 root.querySelectorAll('[data-edit-task]').forEach(el=>add(el,'data-delete-task',el.dataset.editTask,el.textContent.trim()));
 root.querySelectorAll('[data-note]').forEach(el=>add(el,'data-delete-note',el.dataset.note,el.textContent.trim()));
 root.querySelectorAll('[data-edit-habit]').forEach(el=>add(el,'data-delete-habit',el.dataset.editHabit,el.textContent.trim()));
 root.querySelectorAll('[data-matrix-edit]').forEach(el=>{const t=state.tasks.find(t=>t.id===el.dataset.matrixEdit);if(t)add(el,'data-delete-task',t.id,t.title);});
 root.querySelectorAll('[data-matrix-drag][data-matrix-step]').forEach(el=>{if(el.dataset.matrixStep)add(el,'data-delete-step',el.dataset.matrixStep,el.querySelector('label')?.textContent.trim()||'anchor step',{'data-parent-task':el.dataset.matrixDrag});});
 root.querySelectorAll('[data-entry]').forEach(el=>{if(!el.value||el.hasAttribute('data-no-quick-delete'))return;const label=el.getAttribute('aria-label')||'Writing';add(el,'data-clear-entry',el.dataset.entry,label,{'data-entry-label':label});});
}

/* A single paper leaf follows the finger; scrolling and writing retain native gestures. */
let daySwipe=null,swipeTurnProgress=0;
function capturePage(book){if(!book)return null;const copy=book.cloneNode(true);const live=book.querySelectorAll('input,textarea,select');copy.querySelectorAll('input,textarea,select').forEach((f,i)=>{f.value=live[i].value;});const scroll=copy.querySelector('.page-content');if(scroll)scroll.dataset.turnScroll=String(book.querySelector('.page-content').scrollTop);return copy;}
function pageTransform(progress,backwards){const angle=(backwards?1:-1)*progress*178;return `rotateY(${angle}deg) translateZ(${Math.sin(progress*Math.PI)*18}px)`;}
function createPageLeaf(book,departing,backwards){
 book.querySelectorAll('.turn-leaf,.turn-shadow').forEach(e=>e.remove());
 const leaf=document.createElement('div');leaf.className='turn-leaf'+(backwards?' backwards':'');leaf.inert=true;leaf.setAttribute('aria-hidden','true');
 const face=document.createElement('div');face.className='leaf-face';
 const width=book.clientWidth,height=book.clientHeight;
 departing.className='departing-page';departing.style.width=width+'px';departing.style.height=height+'px';departing.style.padding=getComputedStyle(book).padding;
 departing.querySelectorAll('.turn-leaf,.turn-shadow').forEach(e=>e.remove());
 departing.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));
 // cloneNode does not reliably copy the live value or the inner scrolling position.
 
 const scroll=departing.querySelector('.page-content');
 face.append(departing);leaf.append(face);book.append(leaf);if(scroll)scroll.scrollTop=Number(scroll.dataset.turnScroll)||0;
 const shadow=document.createElement('div');shadow.className='turn-shadow'+(backwards?' backwards':'');shadow.setAttribute('aria-hidden','true');book.append(shadow);
 return {leaf,shadow,backwards};
}
function positionPage(turn,progress){turn.leaf.style.transform=pageTransform(progress,turn.backwards);turn.shadow.style.opacity=String(Math.sin(progress*Math.PI)*.55);turn.shadow.style.transform=`scaleX(${Math.max(.05,1-progress)})`;}
function animatePageTurn(book,departing,backwards,progress=0){
 const turn=createPageLeaf(book,departing,backwards);positionPage(turn,progress);
 const animation=turn.leaf.animate([{transform:pageTransform(progress,backwards),opacity:1},{transform:pageTransform(1,backwards),opacity:0}],{duration:Math.max(140,340*(1-progress)),easing:'cubic-bezier(.2,.65,.25,1)',fill:'forwards'});
 turn.shadow.animate([{opacity:.4},{opacity:0}],{duration:340,fill:'forwards'});
 const finish=()=>{turn.leaf.remove();turn.shadow.remove();};animation.onfinish=finish;animation.oncancel=finish;
}
function cancelDaySwipe(){const s=daySwipe;daySwipe=null;if(!s?.turn)return;const t=s.turn;const animation=t.leaf.animate([{transform:pageTransform(s.progress,t.backwards)},{transform:pageTransform(0,t.backwards)}],{duration:140,easing:'ease-out'});animation.onfinish=()=>{t.leaf.remove();t.shadow.remove();};}
app.addEventListener('pointerdown',e=>{
 if(e.pointerType!=='touch'||!e.isPrimary||closed||section!=='calendar'||view!=='day'||modal.open)return;
 if(e.target.closest('button,input,textarea,select,a,canvas,[contenteditable],.month-tabs,.section-tabs,.named-ribbons')||window.getSelection()?.toString())return;
 const book=e.target.closest('[data-day-swipe]');if(!book)return;
 daySwipe={id:e.pointerId,x:e.clientX,y:e.clientY,time:performance.now(),date,book,progress:0};
});
app.addEventListener('pointermove',e=>{
 const s=daySwipe;if(!s||e.pointerId!==s.id)return;
 const dx=e.clientX-s.x,dy=e.clientY-s.y;
 if(!s.turn){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){cancelDaySwipe();return;}if(Math.abs(dx)<8||Math.abs(dx)<Math.abs(dy)*1.2)return;
 s.backwards=dx>0;s.book.setPointerCapture(e.pointerId);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)s.turn=createPageLeaf(s.book,capturePage(s.book),s.backwards);s.horizontal=true;}
 const distance=Math.max(0,(s.backwards?1:-1)*dx);s.progress=Math.min(.8,distance/(s.book.clientWidth*.55));if(s.turn)positionPage(s.turn,s.progress);
});
app.addEventListener('pointercancel',cancelDaySwipe);
app.addEventListener('pointerup',e=>{
 const s=daySwipe;if(!s||s.id!==e.pointerId)return;
 const dx=e.clientX-s.x,dy=e.clientY-s.y,elapsed=performance.now()-s.time;
 if(closed||section!=='calendar'||view!=='day'||s.date!==date||modal.open||Math.abs(dx)<24||Math.abs(dx)<Math.abs(dy)*1.2||elapsed>2500||window.getSelection()?.toString()){cancelDaySwipe();return;}
 daySwipe=null;s.turn?.leaf.remove();s.turn?.shadow.remove();swipeTurnProgress=s.progress;navigate(dx<0?1:-1);
});

function renderLegacyGoals(){return `<div style="display:flex;justify-content:flex-end;margin-bottom:12px">${tools()}</div><section class="side-section"><h2>The bigger picture</h2>${ruled(`goals:${year()}:year`,'Your goals for the year','style="min-height:100px;height:100px"')}</section><div class="goals-grid">${months.map((m,i)=>`<section class="goal-box"><h2>${m}</h2>${ruled(`goals:${year()}:${i}`,`Goals for ${m}`)}<div class="goal-actions"><button class="text-action" data-goal-task="${i}">Make a task from this goal</button></div></section>`).join('')}</div>`;}
function plannerRecords(){return Object.keys(state.entries).filter(k=>/^form:[a-z0-9-]+:type$/.test(k)).map(k=>{const key=k.split(':')[1],type=entry(k),template=plannerTemplates.find(t=>t.id===type);return template?{key,template,title:entry(`form:${key}:title`)||template.title,archived:entry(`form:${key}:archived`)==='yes',pinned:entry(`form:${key}:pinned`)==='yes'}:null;}).filter(Boolean);}
function plannerKey(field){return `form:${plannerPage}:${field}`;}
function plannerTitle(){if(plannerPage==='legacy')return 'Your existing goals';const r=plannerRecords().find(r=>r.key===plannerPage);return r?r.title:plannerPinned?'My forms':'Plan & Organise';}
function plannerField(field,label,type='text'){const k=plannerKey(field);return `<label class="planner-label">${esc(label)}<input type="${type}" data-entry="${k}" data-no-writing-tools data-no-quick-delete aria-label="${esc(label)}" value="${esc(entry(k))}"></label>`;}
function renderPlanner(){
 if(plannerPage==='legacy')return `<button class="secondary" data-planner-home>All forms</button>${renderLegacyGoals()}`;
 const records=plannerRecords(),record=records.find(r=>r.key===plannerPage);
 if(record){const t=record.template,f=plannerFlows[t.id],count=Math.min(100,Math.max(4,Number(entry(plannerKey('rows')))||4));return `<div class="planner-toolbar"><button class="secondary" data-planner-home>${plannerPinned?'My forms':'All forms'}</button><button class="secondary" data-planner-pin="${record.key}" aria-pressed="${record.pinned}">${record.pinned?'Remove from My forms':'Add to My forms tab'}</button><button class="text-action" data-planner-archive="${record.key}">${record.archived?'Restore this form':'Archive this form'}</button></div><div class="planner-meta">${plannerField('title','Name this form')}${plannerField('date',t.group==='plan'?'Target date (optional)':'Review date (optional)','date')}</div><section class="planner-section"><h2>1. ${esc(f.contextTitle)}</h2><p class="planner-guide">${esc(f.contextGuide)}</p>${ruled(plannerKey('flow-context'),f.contextTitle,'data-no-quick-delete data-no-writing-tools')}</section><section class="planner-register"><h2>2. ${esc(f.tableTitle)}</h2><p class="planner-guide">One item per row. Fill only what helps; add rows as you need them. Tick a row when finished.</p><div class="planner-table-scroll"><table class="planner-table"><thead><tr><th scope="col">Done</th>${f.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:count},(_,r)=>`<tr class="${entry(plannerKey('flow-done-'+r))==='yes'?'planner-row-done':''}"><td><button class="habit-check ${entry(plannerKey('flow-done-'+r))==='yes'?'checked':''}" data-planner-done="${r}" aria-label="Mark row ${r+1} done" aria-pressed="${entry(plannerKey('flow-done-'+r))==='yes'}">${entry(plannerKey('flow-done-'+r))==='yes'?'✓':''}</button></td>${f.columns.map((c,i)=>`<td>${ruled(plannerKey(`flow-cell-${r}-${i}`),`${c}, row ${r+1}`,'data-no-quick-delete data-no-writing-tools')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${count<100?'<button class="text-action" data-planner-row>Add a row</button>':''}</section><details class="planner-extra" ${entry(plannerKey('flow-note'))?'open':''}><summary>3. ${esc(f.noteTitle)} (optional)</summary><p class="planner-guide">${esc(f.noteGuide)}</p>${ruled(plannerKey('flow-note'),f.noteTitle,'data-no-quick-delete data-no-writing-tools')}</details>${plannerPrevious(record,count)}<details class="planner-extra" ${entry(plannerKey('next'))?'open':''}><summary>Create a task or reserve time</summary><p class="planner-guide">Choose an action from your list to send to your to-do list or calendar.</p>${ruled(plannerKey('next'),'Action to schedule','data-no-quick-delete data-no-writing-tools')}<div class="planner-toolbar"><button class="secondary" data-planner-task>Make a task</button><button class="secondary" data-planner-event>Schedule time</button><span class="planner-saving" data-saving-status></span></div></details>`;}
 if(plannerPinned){plannerPage=null;const pinned=records.filter(r=>r.pinned&&!r.archived);return `<div class="planner-toolbar"><button class="secondary" data-planner-library>Browse all forms</button></div><div class="planner-cards">${pinned.map(r=>`<button class="planner-card" data-planner-open="${r.key}"><strong>${esc(r.title)}</strong><span>${esc(r.template.title)}</span></button>`).join('')||'<p class="empty-note">Open a saved form and choose “Add to My forms tab” to keep it here.</p>'}</div>`;}

 plannerPage=null;const active=records.filter(r=>!r.archived),archived=records.filter(r=>r.archived);
 return `<div class="planner-hub"><nav class="planner-group-tabs" aria-label="Form collections"><button data-planner-group="plan" aria-pressed="${plannerGroup==='plan'}">Plan something <span>20</span></button><button data-planner-group="organise" aria-pressed="${plannerGroup==='organise'}">Organise everyday life <span>20</span></button></nav><div class="planner-hub-layout"><section><label class="planner-search-label">Find a form<input type="search" id="planner-search" data-no-writing-tools placeholder="Try holiday, routine, learning…" autocomplete="off"></label><div class="planner-cards">${plannerTemplates.filter(t=>t.group===plannerGroup).map(t=>`<button class="planner-card" data-planner-template="${t.id}" data-planner-match="${esc((t.title+' '+t.summary).toLowerCase())}"><strong>${esc(t.title)}</strong><span>${esc(t.summary)}</span></button>`).join('')}</div><p id="planner-no-match" class="empty-note" hidden>No matching forms in this collection. Try the other collection or a shorter search.</p></section><aside class="planner-saved"><h2>Your saved forms</h2>${active.map(r=>`<button class="planner-saved-item" data-planner-open="${r.key}"><strong>${esc(r.title)}</strong><span>${esc(r.template.title)}${entry(`form:${r.key}:date`)?' · '+esc(entry(`form:${r.key}:date`)):''}</span></button>`).join('')||'<p class="planner-guide">Choose a form to begin. Each copy can have its own name.</p>'}${archived.length?`<details><summary>Archived forms (${archived.length})</summary>${archived.map(r=>`<button class="planner-saved-item" data-planner-open="${r.key}">${esc(r.title)}</button>`).join('')}</details>`:''}<button class="text-action planner-legacy" data-planner-legacy>Your existing goals</button></aside></div></div>`;
}
function plannerPrevious(record,count){const t=record.template,hasOld=t.sections.some((_,i)=>entry(plannerKey('section-'+i)))||Array.from({length:count},(_,r)=>t.columns.some((_,c)=>entry(plannerKey(`cell-${r}-${c}`)))).some(Boolean);if(!hasOld)return '';return `<details class="planner-extra"><summary>Your previous answers</summary><p class="planner-guide">Your earlier writing is kept here with its original headings. You can still edit it.</p>${t.sections.map((x,i)=>entry(plannerKey('section-'+i))?`<section><h2>${esc(x.title)}</h2>${ruled(plannerKey('section-'+i),x.title,'data-no-quick-delete data-no-writing-tools')}</section>`:'').join('')}<div class="planner-table-scroll"><table class="planner-table"><thead><tr>${t.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:count},(_,r)=>t.columns.some((_,c)=>entry(plannerKey(`cell-${r}-${c}`)))?`<tr>${t.columns.map((c,i)=>`<td>${ruled(plannerKey(`cell-${r}-${i}`),`${c}, previous row ${r+1}`,'data-no-quick-delete data-no-writing-tools')}</td>`).join('')}</tr>`:'').join('')}</tbody></table></div></details>`;}
function plannerNew(type){const t=plannerTemplates.find(t=>t.id===type);if(!t)return;openModal('Start '+esc(t.title),`<form id="planner-create" data-template="${t.id}"><label class="planner-label">Name this form<input name="title" type="text" maxlength="120" value="${esc(t.title)}" required autofocus></label><p>${esc(t.summary)}</p><div class="modal-footer"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button type="submit" class="primary">Create form</button></div></form>`);}
function plannerClick(data){
 if('plannerLibrary'in data){plannerPinned=false;plannerPage=null;section='goals';render();return true;}
 if(data.plannerPin){const k=`form:${data.plannerPin}:pinned`;state.entries[k]=entry(k)==='yes'?'no':'yes';if(entry(k)==='yes')state.entries[`form:${data.plannerPin}:archived`]='no';save();render();toast(entry(k)==='yes'?'Added to My forms.':'Removed from My forms.');return true;}
 if('plannerDone'in data){const k=plannerKey('flow-done-'+data.plannerDone);state.entries[k]=entry(k)==='yes'?'no':'yes';save();render();return true;}

 if(data.plannerGroup){plannerPinned=false;plannerGroup=data.plannerGroup;plannerPage=null;render();return true;}
 if('plannerHome'in data){plannerPage=null;render();return true;}
 if('plannerLegacy'in data){plannerPage='legacy';render();return true;}
 if(data.plannerTemplate){plannerNew(data.plannerTemplate);return true;}
 if(data.plannerOpen){section='goals';closed=false;plannerPage=data.plannerOpen;render();return true;}
 if(data.plannerArchive){const k=`form:${data.plannerArchive}:archived`;state.entries[k]=entry(k)==='yes'?'no':'yes';save();plannerPage=null;render();return true;}
 if('plannerRow'in data){state.entries[plannerKey('rows')]=String(Math.min(100,(Number(entry(plannerKey('rows')))||4)+1));save();render();return true;}
 if('plannerTask'in data&&!entry(plannerKey('next')).trim()||'plannerEvent'in data&&!entry(plannerKey('next')).trim()){toast('Write the action you want to schedule first.');return true;}
 if('plannerTask'in data){taskForm(null,entry(plannerKey('next')).split('\n')[0]||plannerTitle());const f=document.querySelector('#task-form');f.querySelector('[name=notes]').value=`From Plan & Organise: ${plannerTitle()}\n${entry(plannerKey('next'))}`;const d=entry(plannerKey('date'));if(d)f.querySelector('[name=date]').value=d;return true;}
 if('plannerEvent'in data){eventForm();const f=document.querySelector('#event-form');f.querySelector('[name=title]').value=entry(plannerKey('next')).split('\n')[0]||plannerTitle();f.querySelector('[name=notes]').value=`From Plan & Organise: ${plannerTitle()}\n${entry(plannerKey('next'))}`;const d=entry(plannerKey('date'));if(d){f.querySelector('[name=date]').value=d;f.querySelector('[name=endDate]').value=d;}return true;}
 return false;
}
document.addEventListener('input',e=>{if(e.target.id==='planner-search'){const q=e.target.value.toLowerCase().trim();let visible=0;app.querySelectorAll('.planner-card').forEach(b=>{b.hidden=!b.dataset.plannerMatch.includes(q);if(!b.hidden)visible++;});document.querySelector('#planner-no-match').hidden=visible>0;}if(e.target.dataset.entry?.startsWith('form:')&&e.target.dataset.entry.endsWith(':title')){const h=app.querySelector('.book-head h1');if(h)h.textContent=e.target.value||'Plan & Organise';}});
